PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS pages(id TEXT PRIMARY KEY,name TEXT NOT NULL,niche TEXT NOT NULL,timezone TEXT NOT NULL DEFAULT 'America/Sao_Paulo',daily_limit INTEGER NOT NULL CHECK(daily_limit BETWEEN 1 AND 5),active INTEGER NOT NULL DEFAULT 1,visual TEXT NOT NULL DEFAULT 'azul',voice TEXT NOT NULL DEFAULT 'none',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS scripts(id TEXT PRIMARY KEY,page_id TEXT NOT NULL REFERENCES pages(id),text TEXT NOT NULL UNIQUE,approved INTEGER NOT NULL DEFAULT 0,origin TEXT NOT NULL,license TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,page_id TEXT NOT NULL REFERENCES pages(id),script_id TEXT NOT NULL UNIQUE REFERENCES scripts(id),local_day TEXT NOT NULL,duration INTEGER NOT NULL CHECK(duration BETWEEN 15 AND 30),status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,lease_token TEXT,lease_until TEXT,error TEXT,voice_warning TEXT,file_key TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS jobs_day ON jobs(page_id,local_day);
CREATE TRIGGER IF NOT EXISTS enforce_daily BEFORE INSERT ON jobs BEGIN
 SELECT CASE WHEN (SELECT COUNT(*) FROM jobs WHERE page_id=NEW.page_id AND local_day=NEW.local_day)>=(SELECT daily_limit FROM pages WHERE id=NEW.page_id) THEN RAISE(ABORT,'daily_limit') END;
END;
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TRIGGER IF NOT EXISTS cap_pages BEFORE INSERT ON pages WHEN (SELECT COUNT(*) FROM pages)>=10 BEGIN SELECT RAISE(ABORT,'capacity_limit'); END;
CREATE TRIGGER IF NOT EXISTS cap_scripts BEFORE INSERT ON scripts WHEN (SELECT COUNT(*) FROM scripts)>=500 BEGIN SELECT RAISE(ABORT,'capacity_limit'); END;
CREATE TRIGGER IF NOT EXISTS cap_jobs BEFORE INSERT ON jobs WHEN (SELECT COUNT(*) FROM jobs)>=100 BEGIN SELECT RAISE(ABORT,'capacity_limit'); END;
